package com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.spec.skill;import com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.identity.StableId;public final class HpCostSpec implements CostSpec{public enum HpLethalPolicy{REJECT_IF_WOULD_KILL,ALLOW_LETHAL}private final StableId nodeId;private final int amount,minimumRemainingHp;private final HpLethalPolicy lethalPolicy;public HpCostSpec(StableId id,int amount,HpLethalPolicy policy,int minimum){if(id==null||policy==null||amount<1||minimum<1)throw new IllegalArgumentException("invalid HP cost");if(policy!=HpLethalPolicy.REJECT_IF_WOULD_KILL)throw new IllegalArgumentException("ALLOW_LETHAL is not exposed in P04");nodeId=id;this.amount=amount;lethalPolicy=policy;minimumRemainingHp=minimum;}public static HpCostSpec safeDefault(StableId id,int amount){return new HpCostSpec(id,amount,HpLethalPolicy.REJECT_IF_WOULD_KILL,1);}@Override public StableId nodeId(){return nodeId;}@Override public String variantKey(){return "HP";}public int amount(){return amount;}public HpLethalPolicy lethalPolicy(){return lethalPolicy;}public int minimumRemainingHp(){return minimumRemainingHp;}}
